from pathlib import Path
from html import escape
D=Path('dist')
copy={
'en':dict(title='No-nonsense biomechanics',label='An interactive biomechanics lab',headline='Understand the movement.<br><em>Make every rep count.</em>',lead='Explore how position changes an exercise. Move the controls, watch the mechanics and see the difference for yourself.',library='Choose an exercise',count='03 interactive simulators',category=['Knee & hip extension','Squat mechanics','Hip extension'],names=['Leg press','Pendulum squat','Hip thrust'],desc=['How do foot position and direction of force change the demands on your quads and glutes?','Explore the pendulum path and how your position changes the mechanics of the squat.','Explore hip extension, joint angles and the role of your foot position.'],cta='Open simulator',note='<strong>A model for understanding.</strong> These simplified, side-view simulations illustrate mechanical trends. They do not measure your individual muscle activation.',footer='English & Russian adaptation',credit='Original concept and simulations by',lang='Choose language'),
'ru':dict(title='Биомеханика без лишних слов',label='Интерактивная лаборатория биомеханики',headline='Поймите движение.<br><em>Тренируйтесь осознанно.</em>',lead='Узнайте, как положение тела меняет упражнение. Двигайте элементы тренажёра, наблюдайте за механикой и сравнивайте.',library='Выберите упражнение',count='03 интерактивных симулятора',category=['Разгибание ног','Механика приседа','Разгибание бедра'],names=['Жим ногами','Маятниковый присед','Ягодичный мост'],desc=['Как положение стоп и направление усилия меняют нагрузку на квадрицепс и ягодичные мышцы?','Изучите траекторию маятника и влияние положения тела на механику приседания.','Посмотрите, как связаны разгибание бедра, углы в суставах и положение стоп.'],cta='Открыть симулятор',note='<strong>Модель для понимания.</strong> Упрощённые симуляции сбоку показывают механические закономерности, а не измеряют активацию ваших мышц.',footer='Версия на английском и русском',credit='Оригинальная идея и симуляторы —',lang='Выбор языка')}
for lang,t in copy.items():
 cards=''
 for i,id in enumerate(['prensa','pendu','hipo']):
  cards+=f'''<a class="card" href="/{lang}/{id}.html"><div class="image"><img src="/assets/{id}.jpg" width="480" height="384" alt="{escape(t['names'][i])}" decoding="async"><span class="number">0{i+1}</span></div><div class="card-body"><span class="category">{t['category'][i]}</span><h2>{t['names'][i]}</h2><p>{t['desc'][i]}</p><span class="card-cta">{t['cta']}<span class="arrow" aria-hidden="true">↗</span></span></div></a>'''
 nav=''.join(f'<a href="/{l}/index.html" lang="{l}" hreflang="{l}" class="{"active" if lang==l else ""}" '+('aria-current="page"' if lang==l else '')+f'>{label}</a>' for l,label in [('en','EN'),('ru','RU')])
 html=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090a0c"><title>{t['title']} · Cualigrafía</title><meta name="description" content="{escape(t['lead'])}"><link rel="stylesheet" href="/assets/style.css"><link rel="alternate" hreflang="en" href="/en/index.html"><link rel="alternate" hreflang="ru" href="/ru/index.html"></head><body><div class="wrap"><header><a class="wordmark" href="/{lang}/index.html">Cualigrafía</a><nav class="languages" aria-label="{t['lang']}">{nav}</nav></header><main><section class="intro"><div class="eyebrow">{t['label']}</div><h1>{t['headline']}</h1><p class="lead">{t['lead']}</p></section><section aria-label="{t['library']}"><div class="section-label"><span>{t['library']}</span><span>{t['count']}</span></div><div class="cards">{cards}</div></section><aside class="note"><span class="symbol" aria-hidden="true">↳</span><p>{t['note']}</p></aside></main><footer><span>{t['footer']}</span><span>{t['credit']} <a href="https://cualigrafia.com/" target="_blank" rel="noopener">Cualigrafía ↗</a></span></footer></div></body></html>'''
 (D/lang).mkdir(exist_ok=True)
 (D/lang/'index.html').write_text(html)
 if lang=='ru': (D/'index.html').write_text(html)
